#include <ranges>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    int values[]{1, 2, 3};
    auto view = std::views::all(values);
    assert(view.front() == 1 && view.back() == 3 && view[1] == 2 && view.size() == 3);
    assert(*view.cbegin() == 1 && view.cend() - view.cbegin() == 3);
}
